import React from 'react';
import Header from '../Components/Header';
import SearchResults from '../Components/SearchResults';
import Footer from './Footer';

function SearchResultsPage() {
  return (
    <>
      <Header />
      <SearchResults />
      <Footer />
    </>
  );
}

export default SearchResultsPage;
